// Length of a beat for the progress strip of the beat indicator: the median of the
// last 5 gaps between consecutive beats, as they arrive here. Falls back to 60 / tempo
// until there is a measurement, and starts over when the tempo changes.
var now = Date.now();
var pos = String(value).split('.');
var bar = parseInt(pos[0]), num = parseInt(pos[1]);
var tempo = get('tempo');
if (!locals.gaps || tempo !== locals.tempo) {
  locals.gaps = [];
  locals.tempo = tempo;
}
var isNext = (bar === locals.bar && num === locals.num + 1) || (bar === locals.bar + 1 && num === 1);
var gap = now - locals.time;
if (isNext && gap > 100 && gap < 4000) {
  locals.gaps.push(gap);
  if (locals.gaps.length > 5) locals.gaps.shift();
}
locals.bar = bar;
locals.num = num;
locals.time = now;
var period = tempo > 0 ? 60 / tempo : 0;
if (locals.gaps.length) {
  var sorted = locals.gaps.slice().sort(function (a, b) { return a - b; });
  var mid = Math.floor(sorted.length / 2);
  period = (sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2) / 1000;
}
set('beat-period', period);

