var names = {
  project: [OSC{/project/param/1/name}, OSC{/project/param/2/name}, OSC{/project/param/3/name}, OSC{/project/param/4/name}, OSC{/project/param/5/name}, OSC{/project/param/6/name}, OSC{/project/param/7/name}, OSC{/project/param/8/name}],
  track: [OSC{/track/param/1/name}, OSC{/track/param/2/name}, OSC{/track/param/3/name}, OSC{/track/param/4/name}, OSC{/track/param/5/name}, OSC{/track/param/6/name}, OSC{/track/param/7/name}, OSC{/track/param/8/name}],
  device: [OSC{/device/param/1/name, Param 1}, OSC{/device/param/2/name, Param 2}, OSC{/device/param/3/name, Param 3}, OSC{/device/param/4/name, Param 4}, OSC{/device/param/5/name, Param 5}, OSC{/device/param/6/name, Param 6}, OSC{/device/param/7/name, Param 7}, OSC{/device/param/8/name, Param 8}]
}
var pages = {
  track: [OSC{/track/page/1/name}, OSC{/track/page/2/name}, OSC{/track/page/3/name}, OSC{/track/page/4/name}, OSC{/track/page/5/name}, OSC{/track/page/6/name}, OSC{/track/page/7/name}, OSC{/track/page/8/name}],
  device: [OSC{/device/page/1/}, OSC{/device/page/2/}, OSC{/device/page/3/}, OSC{/device/page/4/}, OSC{/device/page/5/}, OSC{/device/page/6/}, OSC{/device/page/7/}, OSC{/device/page/8/}]
}
// When the selected "device" is the track itself (Bitwig's track remote controls), its params are
// already shown as track params. It is recognized by having the same page list as the track, or
// the same params on the current page.
function same(a, b) {
  return !!a[0] && a.every(function (x, i) { return (x || "") === (b[i] || "") })
}
var deviceIsTrack = same(pages.track, pages.device) || same(names.track, names.device)
var shown = @{list-mode} === "project" ? ["project"] : !@{show-track} ? ["device"] : deviceIsTrack ? ["track"] : ["track", "device"]
var free = 8
var visible = {}
for (var kind of ["project", "track", "device"]) {
  var show = shown.indexOf(kind) >= 0
  visible[kind] = names[kind].map(function (name) { return show && !!name && free-- > 0 })
}
visible.lists = {}
for (var kind of ["project", "track", "device"]) visible.lists[kind] = shown.indexOf(kind) >= 0
return visible
}}

widgets.onValue:
if (value) {
  if (get('list-mode') === 'project') {
    set('list-mode', 'device')
    set('show-track', 1)
  } else {
    set('show-track', get('show-track') ? 0 : 1)
  }
}
